/// @brief Enumeration for Key Manager errors.
///
/// @since_tizen 2.3
abstract class key_manager_error_e {
  /// < Successful
  static const int CKMC_ERROR_NONE = 0;

  /// < Invalid function parameter
  static const int CKMC_ERROR_INVALID_PARAMETER = -22;

  /// < Out of memory
  static const int CKMC_ERROR_OUT_OF_MEMORY = -12;

  /// < Permission denied
  static const int CKMC_ERROR_PERMISSION_DENIED = -13;

  /// < Device needed to run API is not supported
  static const int CKMC_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Socket error between client and Central Key Manager
  static const int CKMC_ERROR_SOCKET = -31522815;

  /// < Invalid request from client
  static const int CKMC_ERROR_BAD_REQUEST = -31522814;

  /// < Invalid response from Central Key Manager
  static const int CKMC_ERROR_BAD_RESPONSE = -31522813;

  /// < Transmitting request failed
  static const int CKMC_ERROR_SEND_FAILED = -31522812;

  /// < Receiving response failed
  static const int CKMC_ERROR_RECV_FAILED = -31522811;

  /// < Optional password used for saving was incorrect
  static const int CKMC_ERROR_AUTHENTICATION_FAILED = -31522810;

  /// < The output buffer size (passed as parameter) was too small
  static const int CKMC_ERROR_BUFFER_TOO_SMALL = -31522809;

  /// < Central Key Manager has failed for unknown reason
  static const int CKMC_ERROR_SERVER_ERROR = -31522808;

  /// < The database was not unlocked - user did not login
  static const int CKMC_ERROR_DB_LOCKED = -31522807;

  /// < An internal error inside the database
  static const int CKMC_ERROR_DB_ERROR = -31522806;

  /// < Provided alias already exists in the database
  static const int CKMC_ERROR_DB_ALIAS_EXISTS = -31522805;

  /// < No data for given alias
  static const int CKMC_ERROR_DB_ALIAS_UNKNOWN = -31522804;

  /// < CA certificate(s) were unknown and chain could not be created
  static const int CKMC_ERROR_VERIFICATION_FAILED = -31522803;

  /// < Provided file or binary has an invalid format
  static const int CKMC_ERROR_INVALID_FORMAT = -31522802;

  /// < Provided file does not exist or cannot be accessed in the file system
  static const int CKMC_ERROR_FILE_ACCESS_DENIED = -31522801;

  /// < The data is saved as unexportable so it cannot be accessed
  static const int CKMC_ERROR_NOT_EXPORTABLE = -31522800;

  /// < Save key/certificate/pkcs12 failed because of file system error
  static const int CKMC_ERROR_FILE_SYSTEM = -31522799;

  /// < Error of unknown reason
  static const int CKMC_ERROR_UNKNOWN = -31522561;
}

